<script setup lang="ts">
import{useSalesCommand}from'./use-sales-command';import{useSalesScope}from'./use-sales-scope';import{ref,computed,watch,onMounted,onUnmounted}from'vue';import{Plus,X,ArrowLeft,ShoppingBag,PackageCheck,Wallet,Search}from'@lucide/vue';
import ReceiptAdjustmentPicker from './ReceiptAdjustmentPicker.vue';
import SalesDeliveryAdjustment from './SalesDeliveryAdjustment.vue';
const nextSale=ref<string|null>(null),history=ref<any>(null),historyLoading=ref(false),salesSearch=ref(''),paymentFilter=ref('all'),deliveryFilter=ref('all'),pageSize=ref('50'),salesSummary=ref<any>(null),salesTotal=ref(0),salesAsOf=ref('');
const props=defineProps<{staff:any}>(),emit=defineEmits(['unauthorized']);const clinics=ref<any[]>([]),clinic=ref(''),date=ref(''),functions=ref<string[]>([]),rows=ref<any[]>([]),items=ref<any[]>([]),detail=ref<any>(null),stocks=ref<any[]>([]),deliveryStocks=ref<any[]>([]),patients=ref<any[]>([]),query=ref(''),mode=ref(''),form=ref<any>({}),draft=ref<any>(null),confirmed=ref(false),ready=ref(false),loading=ref(false),working=ref(false),error=ref(''),retryConfirmed=ref(false);
let alive=true;const identity=()=>JSON.stringify([props.staff?.accountId,props.staff?.employeeId]),scope=useSalesScope(()=>JSON.stringify([identity(),clinic.value,date.value,salesSearch.value,paymentFilter.value,deliveryFilter.value,pageSize.value])),authScope=useSalesScope(identity);const command=useSalesCommand({owner:()=>props.staff?.accountId&&props.staff?.employeeId?props.staff:null,storage:()=>sessionStorage,read:path=>request(path),send:(path,body)=>request(path,body),completed:async(_path,result)=>{const current=authScope.capture();mode.value='';draft.value=null;await refresh();if(current())await select(result.saleId||result.id);}}),{pending,notice,error:commandError}=command,busy=computed(()=>working.value||command.busy.value);
const has=(f:string)=>functions.value.includes(f),short=(s:string)=>s.slice(0,8).toUpperCase(),fmt=(s:any)=>String(s).replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,''),local=()=>new Date(Date.now()+8*3600000-1000).toISOString().slice(0,19).replace(/:00$/,''),instant=(s:string)=>new Date(s+'+08:00').toISOString(),full=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const methods:Record<string,string>={cash:'现金',wechat:'微信（登记已发生到账）',alipay:'支付宝（登记已发生到账）',bank:'银行',other:'其他'};
class ApiError extends Error{constructor(public status:number,m:string){super(m);}}
async function request(path:string,body?:any){const current=authScope.capture(),a=new AbortController(),t=setTimeout(()=>a.abort(),12000);try{const r=await fetch('/api/v1/sales'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:a.signal});const b=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401&&current())emit('unauthorized');throw new ApiError(r.status,b.message||'请求失败。');}return b;}finally{clearTimeout(t);}}
const queueParams=()=>new URLSearchParams({clinicId:clinic.value,date:date.value,q:salesSearch.value.trim(),payment:paymentFilter.value,delivery:deliveryFilter.value,limit:pageSize.value});
const explain=(e:unknown)=>e instanceof Error?e.message:'操作失败。';

async function initialize(){const current=authScope.begin('initialize');loading.value=true;try{command.restore();const b=await request('/bootstrap');if(!current())return;functions.value=b.functions;clinics.value=b.clinics;clinic.value=b.clinics[0]?.id||'';date.value=b.today;ready.value=true;await refresh();}catch(e){if(current()){error.value=explain(e);if(e instanceof ApiError&&[401,403,409].includes(e.status)){rows.value=[];nextSale.value=null;salesSummary.value=null;}}}finally{if(current())loading.value=false;}}
async function refresh(){if(!ready.value)return initialize();if(!clinic.value)return;const current=scope.begin('queue');loading.value=true;error.value='';salesSummary.value=null;rows.value=[];nextSale.value=null;try{const[b,c]=await Promise.all([request('/queue?'+queueParams()),request('/catalogue?clinicId='+clinic.value)]);if(!current())return;rows.value=b.items;nextSale.value=b.next;salesSummary.value=b.summary;salesTotal.value=b.total;salesAsOf.value=b.asOf;items.value=c.items;if(detail.value)await select(detail.value.id);}catch(e){if(current()){error.value=explain(e);rows.value=[];nextSale.value=null;detail.value=null;}}finally{if(current())loading.value=false;}}
async function moreSales(){if(!nextSale.value||loading.value)return;const current=scope.begin('queue');loading.value=true;error.value='';try{const r=await request('/queue?'+new URLSearchParams([...queueParams(),['cursor',nextSale.value]]));if(!current())return;const ids=new Set(rows.value.map(x=>x.id));rows.value.push(...r.items.filter((x:any)=>!ids.has(x.id)));nextSale.value=r.next;}catch(e){if(current()){error.value=explain(e);if(e instanceof ApiError&&[401,403,409].includes(e.status)){rows.value=[];nextSale.value=null;salesSummary.value=null;}}}finally{if(current())loading.value=false;}}
async function select(id:string){const current=scope.begin('detail');detail.value=null;stocks.value=[];history.value=null;try{const b=await request('/'+id);if(!current())return;detail.value=b.item;stocks.value=b.stocks;}catch(e){if(current()){error.value=explain(e);detail.value=null;}}}
async function readHistory(more=false){if(!detail.value||historyLoading.value)return;const id=detail.value.id,current=scope.begin('history',()=>detail.value?.id||'');historyLoading.value=true;error.value='';try{const r=await request('/'+id+'/history'+(more&&history.value?.nextVersion?'?'+new URLSearchParams({beforeVersion:String(history.value.nextVersion),atVersion:String(history.value.currentVersion),atFingerprint:history.value.historyFingerprint}):''));if(!current())return;history.value={...r,items:more?[...history.value.items,...r.items]:r.items};}catch(e){if(current()){error.value=explain(e);if(e instanceof ApiError&&[401,403,409].includes(e.status))history.value=null;}}finally{if(current.active())historyLoading.value=false;}}
async function findPatients(){if(query.value.trim().length<2){error.value='请输入至少两个字或号码片段。';return;}const current=scope.begin('patients',()=>JSON.stringify([mode.value,query.value,form.value]));working.value=true;try{const r=await request('/patients?clinicId='+clinic.value+'&q='+encodeURIComponent(query.value));if(!current())return;patients.value=r.items;error.value='';}catch(e){if(current())error.value=explain(e);}finally{if(current.active())working.value=false;}}
function close(){if(busy.value||pending.value)return;mode.value='';draft.value=null;}
function open(m:string){if(pending.value||command.isBlocked()){error.value='请先核实原提交。';return;}mode.value=m;error.value='';draft.value=null;confirmed.value=false;
 if(m==='sale'){form.value={patientId:'',patientName:'',lines:[{materialId:'',quantity:'',unitPrice:''}]};query.value='';patients.value=[];}
 if(m==='receipt')form.value={amount:'',paymentMethod:'',receivedAt:local(),actualReceived:false,basis:'',adjustmentIds:[]};
 if(m==='delivery'){deliveryStocks.value=stocks.value.map(s=>({...s}));form.value={deliveredAt:local(),actualDelivered:false,allocationsConfirmed:false,basis:'',adjustmentIds:[],lines:detail.value.lines.map((l:any)=>({...l,allocations:[{stockId:'',quantity:''}]}))};}
}
watch(query,()=>{patients.value=[];},{flush:'sync'});
watch(form,()=>{draft.value=null;confirmed.value=false;},{deep:true});
watch(()=>form.value.deliveredAt,()=>{if(mode.value==='delivery')error.value='';});
function saleBody(){return{clinicId:clinic.value,patientId:form.value.patientId,lines:form.value.lines.map((l:any)=>({materialId:l.materialId,quantity:l.quantity,unitPrice:l.unitPrice}))};}

async function quote(){const current=scope.begin('quote',()=>JSON.stringify([mode.value,form.value]));working.value=true;error.value='';try{const r=await request('/quote',saleBody());if(!current())return;draft.value=r;confirmed.value=false;}catch(e){if(current())error.value=explain(e);}finally{if(current.active())working.value=false;}}
async function send(path:string,body:any,_label:string,retry=false){const current=authScope.capture();retryConfirmed.value=false;const saved=retry?await command.retry():await command.submit(path,body);if(current()&&(saved||pending.value)){mode.value='';draft.value=null;}}
async function retryOriginal(){if(!retryConfirmed.value||command.status.value?.state!=='not_found')return;await send('',null,'',true);}
async function save(){const f=form.value;try{if(mode.value==='sale'){if(!draft.value)return await quote();if(!confirmed.value)return;return await send('',{...saleBody(),requestId:crypto.randomUUID(),quoteToken:draft.value.token},'销售单已建立，尚未收款，也未扣减库存。');}
 if(mode.value==='receipt')return await send('/'+detail.value.id+'/receipt',{requestId:crypto.randomUUID(),version:detail.value.version,...f,receivedAt:instant(f.receivedAt)},'实际全额到账已登记，交付状态保持真实事实。');
 if(mode.value==='delivery'){const allocations=f.lines.flatMap((l:any)=>l.allocations.map((a:any)=>({lineId:l.id,stockId:a.stockId,stockVersion:Number(deliveryStocks.value.find(s=>s.id===a.stockId)?.version)||0,quantity:a.quantity})));return await send('/'+detail.value.id+'/delivery',{requestId:crypto.randomUUID(),version:detail.value.version,allocations,deliveredAt:instant(f.deliveredAt),actualDelivered:f.actualDelivered,allocationsConfirmed:f.allocationsConfirmed,basis:f.basis,adjustmentIds:f.adjustmentIds},'实际整单交付已保存，库存按各真实来源扣减一次。');}}catch(e){error.value=explain(e);}}
watch(()=>clinic.value,()=>{items.value=[];},{flush:'sync'});
watch(()=>JSON.stringify([clinic.value,date.value,salesSearch.value,paymentFilter.value,deliveryFilter.value,pageSize.value]),()=>{rows.value=[];nextSale.value=null;salesSummary.value=null;salesTotal.value=0;salesAsOf.value='';detail.value=null;history.value=null;historyLoading.value=false;stocks.value=[];deliveryStocks.value=[];patients.value=[];draft.value=null;working.value=false;},{flush:'sync'});
watch(()=>detail.value?.id,()=>{history.value=null;historyLoading.value=false;},{flush:'sync'});
watch(identity,()=>{salesSearch.value='';paymentFilter.value='all';deliveryFilter.value='all';pageSize.value='50';functions.value=[];clinics.value=[];clinic.value='';rows.value=[];nextSale.value=null;detail.value=null;history.value=null;stocks.value=[];deliveryStocks.value=[];patients.value=[];query.value='';items.value=[];mode.value='';form.value={};draft.value=null;confirmed.value=false;ready.value=false;loading.value=false;working.value=false;historyLoading.value=false;retryConfirmed.value=false;error.value='';void initialize();},{flush:'sync'});
onUnmounted(()=>{alive=false;});defineExpose({refresh});onMounted(initialize);
</script>

<template><div class="sale-workspace"><div v-if="error" class="b-alert error" role="alert">{{error}}</div><div v-if="notice" class="b-alert success" role="status">{{notice}}</div><div v-if="commandError" class="b-alert error" role="alert">{{commandError}}</div><section v-if="pending" class="b-alert warning"><strong>{{pending.summary}}</strong><template v-if="pending.phase==='pending'"><p>原提交结果不明，请先只读核实；请勿另开单或重复出库。</p><button class="b-button outline" :disabled="busy" @click="retryConfirmed=false;command.verify()">只读核实原办理</button><div v-if="command.status.value?.state==='completed'"><p>查到原成功结果：{{short(command.status.value.resultId)}}，{{command.status.value.version?'原结果第'+command.status.value.version+'版':'原记录已存在，本次未新建版本'}}，保存时间{{full(command.status.value.completedAt)}}。对应原请求，不保证当前表单或后来状态。</p><button class="b-button" :disabled="busy" @click="command.acknowledge()">已核对原结果，仅清理提示</button></div><p v-else-if="command.status.value?.state==='not_found'">本次未见成功记录，可能仍在处理、未提交，或原办理仅返回已有收款/交付。请先查看原业务；未查到不等于没有收款或交付，查询不会补写或自动重试。</p><label v-if="command.status.value?.state==='not_found'" class="b-checkbox"><input type="checkbox" v-model="retryConfirmed" :disabled="busy"/><span>已核对原业务，确认按原请求编号和内容重试</span></label><button v-if="command.status.value?.state==='not_found'" class="b-button" :disabled="busy||!retryConfirmed" @click="retryOriginal">按原请求重试办理</button></template><template v-else><p>{{pending.phase==='confirmed'?'业务已成功，仅本机提示未清理。':'原办理已被拒绝，仅本机提示未清理。'}}</p><button class="b-button" :disabled="busy" @click="command.cleanup()">仅清理本机提示</button></template></section>
 <div class="sale-filters"><label>销售诊所<select v-model="clinic" :disabled="busy||!!pending||!!mode" @change="detail=null;refresh()"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>开单日期<input v-model="date" type="date" :disabled="busy||!!pending||!!mode" @change="detail=null;refresh()"/></label><label>患者姓名筛选<input v-model="salesSearch" :disabled="busy||!!pending||!!mode" maxlength="100" placeholder="输入后点击查询" @keydown.enter.prevent="refresh()"/></label><label>付款情况<select v-model="paymentFilter" :disabled="busy||!!pending||!!mode" @change="refresh()"><option value="all">全部付款情况</option><option value="paid">已付款</option><option value="unpaid">待付款</option></select></label><label>交付情况<select v-model="deliveryFilter" :disabled="busy||!!pending||!!mode" @change="refresh()"><option value="all">全部交付情况</option><option value="delivered">已交付</option><option value="pending">待交付</option></select></label><label>每页销售<select v-model="pageSize" :disabled="busy||!!pending||!!mode" @change="refresh()"><option value="10">10</option><option value="25">25</option><option value="50">50</option></select></label><button class="b-button outline" :disabled="loading||busy||!!mode" @click="refresh()">查询销售</button><button v-if="has('sale.manage')" class="b-button" :disabled="busy||!!pending" @click="open('sale')"><Plus :size="17"/>登记商品销售</button></div>
 <p v-if="loading" class="b-help">正在读取销售与库存…</p>
 <template v-if="!detail"><section class="b-card sale-block"><div class="sale-list-title"><div><h2>商品销售</h2><p>独立开单 · 据实登记全额到账 · 实际整单交付</p></div><ShoppingBag :size="28" :stroke-width="1.4"/></div><div v-if="!rows.length&&!loading" class="b-empty"><ShoppingBag :size="30"/><strong>当前日期和筛选条件下没有销售单</strong><span>开单不会提前占用或扣减库存。</span></div><article v-for="s in rows" :key="s.id" class="sale-row"><div><small>销售 {{short(s.id)}} · {{full(s.openedAt)}}</small><h3>{{s.patientName}}</h3><p>{{s.lines.map((l:any)=>l.name+' × '+fmt(l.quantity)+l.unit).join('；')}}</p><div class="sale-status"><span class="b-pill" :class="s.paymentState==='paid'?'active':''">{{s.paymentState==='paid'?'已付款':'待付款'}}</span><span class="b-pill" :class="s.deliveryState==='delivered'?'active':''">{{s.deliveryState==='delivered'?'已实际交付':'待实际交付'}}</span></div></div><div class="sale-row-end"><strong>¥ {{s.total}}</strong><button class="b-button outline small" @click="select(s.id)">查看 / 办理</button></div></article><button v-if="nextSale" class="b-button outline" :disabled="loading||busy" @click="moreSales">继续加载销售单</button><p v-if="salesSummary" class="b-help">已加载{{rows.length}} / {{salesTotal}}单 · 读取时点{{full(salesAsOf)}}。姓名日期范围共{{salesSummary.total}}单，应付合计{{salesSummary.orderAmount}}元（不是实收收入）；已付{{salesSummary.paid}}、待付{{salesSummary.unpaid}}，已交{{salesSummary.delivered}}、待交{{salesSummary.pending}}。两维统计独立，覆盖完整范围，不随状态筛选或分页缩小。</p><p v-else class="b-help">调整姓名后请查询；付款和交付分别据实登记。</p></section></template>
 <template v-else><button class="f-text sale-back" @click="detail=null"><ArrowLeft :size="16"/>返回销售列表</button><section class="b-card sale-block"><div class="sale-detail-head"><div><div class="b-eyebrow">SALE {{short(detail.id)}}</div><h2>{{detail.patientName}}的商品销售单</h2><p>开单 {{full(detail.openedAt)}} · 第 {{detail.version}} 版</p><p v-if="detail.patientName!==detail.originalPatientName" class="b-help">原开单核对姓名：{{detail.originalPatientName}}</p></div><div class="sale-total"><small>应付合计</small><strong>¥ {{detail.total}}</strong></div></div><div class="sale-table-wrap"><table><thead><tr><th>原采用商品 / 分类</th><th>数量</th><th>成交单价</th><th>小计</th></tr></thead><tbody><tr v-for="l in detail.lines" :key="l.id"><td><strong>{{l.name}}</strong><small>{{l.classification}} · {{l.unit}}</small></td><td>{{fmt(l.quantity)}} {{l.unit}}</td><td>¥ {{fmt(l.unitPrice)}}</td><td>¥ {{l.subtotal}}</td></tr></tbody></table></div><p class="b-help">保留开单时采用的商品、分类、单位和价格；当前目录变化不会回算本单。</p></section>
 <div class="sale-facts"><section class="b-card sale-block"><div class="sale-fact-head"><Wallet :size="22"/><h2>实际收款</h2><span class="b-pill" :class="detail.receipt?'active':''">{{detail.receipt?'已付款':'待付款'}}</span></div><template v-if="detail.receipt"><h3>¥ {{detail.receipt.amount}}</h3><p>{{methods[detail.receipt.method]}}</p><p>实际到账 {{full(detail.receipt.receivedAt)}}<br/>首次登记 {{full(detail.receipt.registeredAt)}}</p><p>{{detail.receipt.basis}}</p></template><template v-else><p>还没有实际到账登记。仅保留待付款，不自动扣款。</p><button v-if="has('receipt.create')" class="b-button outline" :disabled="busy||!!pending" @click="open('receipt')">登记实际全额到账</button></template></section>
 <section class="b-card sale-block"><div class="sale-fact-head"><PackageCheck :size="22"/><h2>实际交付</h2><span class="b-pill" :class="detail.deliveries.length?'active':''">{{detail.deliveries.length?'已交付':'待交付'}}</span></div><template v-if="detail.deliveries.length"><p>实际交付 {{full(detail.deliveries[0].delivered_at)}}</p><article v-for="d in detail.deliveries" :key="d.delivery_line_id" class="sale-delivery"><strong>{{detail.lines.find((l:any)=>l.id===d.sale_line_id)?.name}} · {{fmt(d.delivered_quantity)}} {{detail.lines.find((l:any)=>l.id===d.sale_line_id)?.unit}}</strong><small>批次 {{d.batch_reference||'未提供'}} · 效期 {{d.expires_on||'待核实'}} · 库存 {{short(d.stock_id)}}</small></article><p class="b-help">已按实际分配形成库存变动，无需再登记材料领用。</p></template><template v-else><p>尚未确认实际交付，库存不预留也不扣减。</p><button v-if="has('sale.deliver')" class="b-button outline" :disabled="busy||!!pending" @click="open('delivery')">核对实际整单交付</button></template></section></div></template>
 <section v-if="detail" class="b-card sale-block sale-history"><div class="sale-list-title"><div><h2>销售原版与交付依据</h2><p>逐版查看当时采用的明细和实际办理，后来的收款另在实收历史核对。</p></div><button class="b-button outline small" :disabled="historyLoading" @click="readHistory(false)">{{historyLoading?'正在读取…':'查看销售原版'}}</button></div><template v-if="history"><p class="b-help">当前核对第{{history.currentVersion}}版；原版、人员或来源辅助资料改变时，续页将要求重新打开。</p><article v-for="r in history.items" :key="r.id" class="sale-history-version"><h3>第{{r.version}}版 · {{r.action==='sale.create'?'建立销售单':r.action==='sale.deliver'?'实际整单交付':'销售原版'}}</h3><p>本版登记 {{full(r.recordedAt)}} · {{r.recordedBy}}</p><p>办理依据：{{r.reason||(r.action==='sale.create'?'首次开单核对':'未提供，须核实')}}</p><div class="sale-table-wrap"><table><thead><tr><th>原采用商品 / 分类</th><th>数量</th><th>成交单价</th><th>小计</th></tr></thead><tbody><tr v-for="l in r.lines" :key="l.id"><td><strong>{{l.name}}</strong><small>{{l.classification}} · {{l.unit}}</small></td><td>{{fmt(l.quantity)}} {{l.unit}}</td><td>¥ {{fmt(l.unitPrice)}}</td><td>¥ {{l.subtotal}}</td></tr></tbody></table></div><p><strong>本版应付合计 ¥ {{r.total}}</strong>，不代表本版发生收款。</p><template v-if="r.deliveries.length"><p>本版实际交付 {{full(r.deliveries[0].deliveredAt)}}</p><p v-for="d in r.deliveries" :key="d.id">{{r.lines.find((l:any)=>l.id===d.lineId)?.name}} · {{fmt(d.quantity)}} {{r.lines.find((l:any)=>l.id===d.lineId)?.unit}} · 库存 {{short(d.stockId)}} · 批次 {{d.batch||'未提供'}} · 效期 {{d.expiresOn||'待核实'}}</p><p v-if="r.adjustmentIds.length" class="b-help">本版采用调整轮次：{{r.adjustmentIds.map(short).join('、')}}</p></template><p v-else class="b-help">本版没有交付登记，不拼入后来发生的交付。</p></article><button v-if="history.nextVersion" class="b-button outline" :disabled="historyLoading" @click="readHistory(true)">继续加载更早原版</button><button class="f-text" @click="history=null">收起销售原版</button></template></section>
 <div v-if="mode" class="b-backdrop"><form class="b-dialog sale-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button type="button" class="b-close" aria-label="关闭销售办理" :disabled="busy||!!pending" @click="close"><X :size="21"/></button><div class="b-eyebrow">PRODUCT SALES</div><h2>{{mode==='sale'?'核对商品销售':mode==='receipt'?'登记实际全额到账':'核对实际整单交付'}}</h2><div v-if="error" class="b-alert error" role="alert">{{error}}</div>
 <template v-if="mode==='sale'"><label>查找已有患者<input v-model="query" maxlength="100" placeholder="输入至少两个字或联系电话片段"/></label><button type="button" class="b-button outline small" :disabled="busy" @click="findPatients"><Search :size="15"/>检索患者</button><div class="sale-patient-options"><button v-for="p in patients" :key="p.id" type="button" :class="{selected:form.patientId===p.id}" @click="form.patientId=p.id;form.patientName=p.name"><strong>{{p.name}}</strong><span>{{p.phone||'联系电话未提供'}}</span></button><p v-if="query.length>=2&&!patients.length" class="b-help">检索后在结果中核对选择，不按同名或手机号自动合并。</p></div><p class="sale-selected">购买患者：{{form.patientName||'请先检索并选择'}}</p><div class="sale-subheading"><strong>商品和成交数量价格</strong><button type="button" class="b-button outline small" :disabled="form.lines.length>=20" @click="form.lines.push({materialId:'',quantity:'',unitPrice:''})"><Plus :size="14"/>加一行</button></div><div v-for="(l,k) in form.lines" :key="k" class="sale-edit-line"><label>商品<select v-model="l.materialId" required><option value="">请选择实际购买商品</option><option v-for="m in items" :key="m.id" :value="m.id">{{m.name}} · {{m.specification||m.classification}} · {{m.unit}}</option></select></label><div class="b-two-fields"><label>销售数量（{{items.find(m=>m.id===l.materialId)?.unit||'先选商品'}}）<input v-model="l.quantity" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?" required/></label><label>成交单价（元 / {{items.find(m=>m.id===l.materialId)?.unit||'单位'}}）<input v-model="l.unitPrice" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?" required/></label></div><button v-if="form.lines.length>1" class="f-text" type="button" @click="form.lines.splice(k,1)">移除此未保存行</button></div>
 <div v-if="draft" class="sale-quote"><strong>销售草稿 · {{draft.patient.name}}</strong><p v-for="(l,k) in draft.lines" :key="k">{{l.name}} · {{fmt(l.quantity)}} {{l.unit}} × ¥{{fmt(l.unitPrice)}} = ¥{{l.subtotal}}</p><h3>合计 ¥ {{draft.total}}</h3><p class="b-help">当前库存已核对。此时未开单、不收款、不占库存；确认时再次检查。</p><label class="b-checkbox"><input type="checkbox" v-model="confirmed" required/><span>已核对患者、全部商品、数量、成交价和合计，确认建立销售单。</span></label></div><p v-else class="b-help">先填写明确数量和成交价，再计算核对。没有默认数量或默认售价。</p></template>
 <template v-if="mode==='receipt'"><div class="f-context">{{detail.patientName}} · 销售 {{short(detail.id)}} · 应付 ¥{{detail.total}}</div><label>已核实实际到账金额（元）<input v-model="form.amount" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" required/></label><label>实际付款方式<select v-model="form.paymentMethod" required><option value="">请选择真实方式</option><option v-for="(label,key) in methods" :key="key" :value="key">{{label}}</option></select></label><label>实际到账时间<input v-model="form.receivedAt" type="datetime-local" step="1" required/></label><label>真实到账或补录依据<textarea v-model="form.basis" required rows="3" maxlength="1500"/></label><ReceiptAdjustmentPicker v-model="form.adjustmentIds" :clinic-id="clinic" kind="sale" :received-at="instant(form.receivedAt)" :disabled="busy||!!pending"/><label class="b-checkbox"><input v-model="form.actualReceived" type="checkbox" required/><span>前台已核实全额真实到账；这是登记已经发生的收款，不发起支付。</span></label></template>
 <template v-if="mode==='delivery'"><div class="f-context">{{detail.patientName}} · 销售 {{short(detail.id)}} · {{detail.paymentState==='paid'?'已付款':'待付款'}}，与实际交付分别记录</div><p class="b-help">逐原行填写实际库存来源和数量，全部原行须完整交付。分配同一库存的数量会合并核对，不按开单时间预留。</p><article v-for="l in form.lines" :key="l.id" class="sale-edit-line"><strong>{{l.name}} · 本行应交付 {{fmt(l.quantity)}} {{l.unit}}</strong><div v-for="(a,k) in l.allocations" :key="k" class="sale-allocation"><label>实际库存来源<select v-model="a.stockId" required><option value="">请核对实际来源批次及效期</option><option v-for="s in deliveryStocks.filter(s=>s.materialId===l.materialId)" :key="s.id" :value="s.id">{{s.batch||'未提供批次'}} · {{s.expiresOn||'效期待核实'}} · 当前{{fmt(s.quantity)}}{{s.unit}} · {{short(s.id)}}</option></select></label><label>本来源实际交付数量（{{l.unit}}）<input v-model="a.quantity" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?" required/></label><button v-if="l.allocations.length>1" type="button" class="f-text" @click="l.allocations.splice(k,1)">移除此未保存分配</button></div><button type="button" class="b-button outline small" :disabled="l.allocations.length>=10" @click="l.allocations.push({stockId:'',quantity:''})"><Plus :size="14"/>增加本行库存来源</button></article><label>整单实际交付时间<input v-model="form.deliveredAt" type="datetime-local" step="1" required/></label><SalesDeliveryAdjustment v-model="form.adjustmentIds" :sale-id="detail.id" :delivered-at="form.deliveredAt?instant(form.deliveredAt):''" :disabled="busy||!!pending"/><label>实际交付及来源核对依据<textarea v-model="form.basis" required maxlength="1500" rows="3"/></label><label class="b-checkbox"><input v-model="form.actualDelivered" type="checkbox" required/><span>已核实本单全部商品实际交付，未将待交付推定为已交付。</span></label><label class="b-checkbox"><input v-model="form.allocationsConfirmed" type="checkbox" required/><span>已核对实际来源、批次效期资料、单位和逐行数量；未知资料没有猜填，分配与现场事实一致。</span></label></template>
 <button class="b-button full" :disabled="busy||(mode==='sale'&&!form.patientId)">{{busy?'正在办理…':mode==='sale'?(draft?'确认建立销售单':'计算并核对销售草稿'):mode==='receipt'?'确认登记实际全额到账':'确认整单交付并扣库存'}}</button>
 </form></div></div></template>
<style scoped>.sale-filters{flex-wrap:wrap}.sale-filters label{min-width:180px;flex:1 1 180px}.sale-filters label:first-child{max-width:none}@media(max-width:760px){.sale-filters label{flex:1 1 100%;min-width:0}.sale-filters>.b-button{flex:1}}.sale-history-version{margin:18px 0;padding:20px;background:#f5f8f0;border:1px solid #dce7da;border-radius:12px}.sale-history-version p{line-height:1.75;overflow-wrap:anywhere}.sale-history-version h3{margin-top:0}.sale-history .f-text{margin:14px 0}@media(max-width:760px){.sale-history .sale-list-title{flex-wrap:wrap;gap:12px}.sale-history-version{padding:14px}}</style>
